// Tomamos TODAS las filas que salieron del CSV
const todasLasFilas = items.map(item => item.json);

// Las convertimos en un solo texto gigante
const textoContexto = JSON.stringify(todasLasFilas);

// Devolvemos UN SOLO ítem con todo el texto
return [{
    json: {
        contexto_entrenamiento: textoContexto
    }
}];

// 1. Recolectamos el código generado por la IA (Scripts de prueba)
// (Asegúrate de que tu Gemini devuelve 'text' o ajusta esta parte)
const scriptsGenerados = items.map(item => item.json.text || item.json.output);

// 2. Unimos todos los scripts con un separador visual claro
const contenidoUnido = scriptsGenerados.join('\n\n---\n\n');

// 3. Agregamos un Título Principal y la fecha
const fecha = new Date().toISOString().split('T')[0];
const documentoFinal = `# Reporte de Scripts de Prueba Automatizados (S1)\n> Generado el: ${fecha}\n\n${contenidoUnido}`;

// 4. Devolvemos el paquete listo para subir a Azure
return [{
    json: {
        contenido_wiki: documentoFinal
    }
}];

// 1. Validamos que haya contenido en el nodo anterior
if (!items[0].json.content) {
  return [{ json: { error: "No se pudo leer el contenido de la Wiki." } }];
}

const content = items[0].json.content;

// 2. REGEX PARA CAPTURAR BLOQUES DE HU
// Busca: ### Nro. HU-XX - Título: ... (hasta el siguiente separador o fin de archivo)
const regex = /###\s*Nro\.\s*HU-?(\d+)\s*-\s*Título:\s*([^\n\r]+)([\s\S]*?)(?=\n\s*---\s*\n|$)/gi;

let match;
const paquetes = [];

while ((match = regex.exec(content)) !== null) {
  const idRaw = match[1];             // Ej: "03"
  const tituloRaw = match[2].trim();  // Ej: "Publicar oferta"
  const cuerpoRaw = match[3];         // El contenido (Tablas, Criterios)

  // Formateamos el ID con el prefijo HU
  const idHuFormatted = `HU-${idRaw}`;

  // Reconstruimos el bloque completo para pasarlo al LLM
  // (Esto incluye la tabla y el glosario para que la IA tenga contexto)
  const bloqueCompleto = `### Nro. ${idHuFormatted} - Título: ${tituloRaw}\n${cuerpoRaw}`;

  // Solo guardamos si detectamos contenido real (> 20 caracteres)
  if (cuerpoRaw.length > 20) {
    paquetes.push({
      json: {
        id_hu: idHuFormatted,    // <--- AHORA SE LLAMA 'id_hu'
        titulo: tituloRaw,
        input_para_llm: bloqueCompleto.trim(), 
        // NO HAY CAMPO 'DESCRIPCION' AQUÍ
      }
    });
  }
}

// 3. Validación final
if (paquetes.length === 0) {
    return [{ json: { warning: "No se encontraron bloques con el formato '### Nro. HU-...'" } }];
}

return paquetes;

// 1. Obtenemos el contenido
const content = items[0].json.content;

if (!content) {
  return [{ json: { error: "El nodo HTTP no trajo contenido." } }];
}

// 2. ESTRATEGIA: DIVIDIR POR CABECERAS DE HU
const splitRegex = /(?:\r?\n|^)(?=(?:#{1,6}\s*|[\*_]*)\s*(?:Nro\.?)?\s*HU\s*-?\s*\d+)/i;

const bloques = content.split(splitRegex);
const historias = [];

bloques.forEach(bloque => {
  const texto = bloque.trim();

  // A. EXTRAER ID Y TÍTULO (Método ultra resistente)
  const idMatch = texto.match(/HU\s*-?\s*(\d+)/i);

  if (idMatch) {
    const idNum = idMatch[1];

    // Extraer el título limpiando la primera línea de cualquier símbolo
    const firstLine = texto.split(/\r?\n/)[0];
    const tituloLimpio = firstLine
        .replace(/#{1,6}/g, '')
        .replace(/\*/g, '')
        .replace(/Nro\.?/i, '')
        .replace(new RegExp(`HU\\s*-?\\s*${idNum}`, 'i'), '')
        .replace(/-\s*Título\s*:/i, '')
        .replace(/Título\s*:/i, '')
        .replace(/^[-\s:|]+/, '') // Quita guiones o espacios al inicio
        .trim();

    // --- B. EXTRAER DESCRIPCIÓN ---
    let descripcion = "Descripción no detectada";
    // Regex Lookahead: Busca hasta que encuentre una Matriz o un Paso en una nueva línea
    const regexLookahead = /(?=\r?\n[ \t]*(?:#{1,6}|\*\*)?[ \t]*(?:PASO\s+\d+|Matriz\s+de))/i;

    // Busca la etiqueta "Descripción:"
    const regexDesc = new RegExp(`Descripción\\s*:?\\s*([\\s\\S]*?)${regexLookahead.source}`, 'i');
    const descMatch = texto.match(regexDesc);

    if (descMatch) {
        descripcion = descMatch[1].trim();
    } else {
        // Respaldo: Formato COMO... QUIERO... PARA...
        const regexNarrativa = new RegExp(`(COMO\\s+[\\s\\S]+?QUIERO\\s+[\\s\\S]+?PARA\\s+[\\s\\S]+?)(?:\\.|${regexLookahead.source})`, 'i');
        const narrativaMatch = texto.match(regexNarrativa);
        if (narrativaMatch) {
            descripcion = narrativaMatch[1].replace(/\|/g, '').trim(); 
        }
    }

    // --- C. EXTRAER TODAS LAS MATRICES (Resistente a falta de '#') ---
    // Atrapa todo desde "PASO X" o "Matriz de..." hasta el siguiente "GLOSARIO"
    const regexMatriz = /(?:^|\r?\n)[ \t]*(?:#{1,6}|\*\*)?[ \t]*(?:PASO\s+\d+|Matriz\s+de)[\s\S]*?(?=(?:\r?\n[ \t]*(?:#{1,6}|\*\*)?[ \t]*GLOSARIO)|$)/gi;
    let matricesExtraidas = [];
    let matchM;
    while ((matchM = regexMatriz.exec(texto)) !== null) {
        matricesExtraidas.push(matchM[0].trim());
    }
    let matriz = matricesExtraidas.length > 0 ? matricesExtraidas.join("\n\n") : "Matriz no detectada";

    // --- D. EXTRAER TODOS LOS GLOSARIOS (Resistente a falta de '#') ---
    // Atrapa todo desde "GLOSARIO" hasta el siguiente "PASO X" o "Matriz de..."
    const regexGlosario = /(?:^|\r?\n)[ \t]*(?:#{1,6}|\*\*)?[ \t]*GLOSARIO[\s\S]*?(?=(?:\r?\n[ \t]*(?:#{1,6}|\*\*)?[ \t]*(?:PASO\s+\d+|Matriz\s+de))|$)/gi;
    let glosariosExtraidos = [];
    let matchG;
    while ((matchG = regexGlosario.exec(texto)) !== null) {
        glosariosExtraidos.push(matchG[0].trim());
    }
    let glosario = glosariosExtraidos.length > 0 ? glosariosExtraidos.join("\n\n") : "Glosario no detectado";

    // Guardamos el objeto completo
    historias.push({
      json: {
        id_hu: `HU-${idNum}`,
        titulo: tituloLimpio,
        descripcion: descripcion,
        tabla_decision_generada: matriz, 
        glosario_acciones: glosario      
      }
    });
  }
});

// 3. RESULTADO
if (historias.length === 0) {
    return [{ 
        json: { 
            warning: "No se detectaron historias con el formato esperado.",
            texto_inicio: content.substring(0, 500) 
        } 
    }];
}

return historias;
